"""Build INDEX.md from the repository's vctx schema-5 pack."""

import argparse
import json
import math
import re
import sys
import tempfile
from pathlib import Path, PurePosixPath
from urllib.parse import quote, urlsplit


ROOT = Path(__file__).resolve().parent.parent
MANIFEST = ROOT / "sources" / "manifest.json"
INDEX = ROOT / "INDEX.md"
MARKDOWN = re.compile(r"([\\`*_[\]{}()<>#+\-.!|])")
HEADER = (
    "# Recordings\n\n"
    "<!-- Generated by `python tools/build_index.py`; do not edit manually. -->\n\n"
)


class CatalogError(ValueError):
    """The pack cannot produce a complete, safe index."""


def _require(condition: bool, message: str) -> None:
    if not condition:
        raise CatalogError(message)


def _object(path: Path) -> dict:
    value = json.loads(path.read_text(encoding="utf-8"))
    _require(isinstance(value, dict), f"expected a JSON object: {path}")
    return value


def _text(value: object, name: str) -> str:
    _require(isinstance(value, str) and bool(value), f"{name} must be a non-empty string")
    _require(
        not any(ord(character) < 32 or ord(character) == 127 for character in value),
        f"{name} contains control characters",
    )
    return value


def _path(root: Path, value: object, name: str) -> tuple[PurePosixPath, Path]:
    raw = _text(value, name)
    relative = PurePosixPath(raw)
    safe = (
        "\\" not in raw
        and not relative.is_absolute()
        and raw == relative.as_posix()
        and not any(part in {"", ".", ".."} for part in relative.parts)
    )
    _require(safe, f"unsafe {name}: {raw}")
    resolved = (root / Path(*relative.parts)).resolve()
    _require(resolved.is_relative_to(root.resolve()), f"unsafe {name}: {raw}")
    return relative, resolved


def _artifact(source: dict, lane: Path, kind: str) -> tuple[PurePosixPath, Path]:
    artifacts = source.get("artifacts")
    _require(isinstance(artifacts, list), "source artifacts must be a list")
    matches = [item for item in artifacts if isinstance(item, dict) and item.get("kind") == kind]
    _require(len(matches) == 1, f"source must declare exactly one {kind} artifact")
    return _path(lane, matches[0].get("path"), f"{kind} artifact path")


def _duration(value: object, name: str) -> tuple[float, str]:
    _require(
        not isinstance(value, bool) and isinstance(value, (int, float)),
        f"{name} must be a number",
    )
    total = float(value)
    _require(
        math.isfinite(total) and total >= 0,
        f"{name} must be finite and non-negative",
    )
    hours, remainder = divmod(int(total + 0.5), 3600)
    minutes, seconds = divmod(remainder, 60)
    return total, f"{hours:02d}:{minutes:02d}:{seconds:02d}"


def _entry(
    sources: Path,
    source: object,
) -> tuple[str, str, str, str, str]:
    _require(isinstance(source, dict), "manifest source must be an object")
    source_id = source["id"]
    lane_path, lane = _path(sources, source.get("path"), "source path")
    _require(source.get("status") == "ok", f"source is not ready: {source_id}")
    _, metadata_path = _artifact(source, lane, "metadata")
    read_path, read_file = _artifact(source, lane, "read")
    _require(read_file.is_file(), f"missing read artifact: {read_file}")

    metadata = _object(metadata_path)
    _require(metadata.get("id") == source_id, f"metadata id does not match manifest: {source_id}")
    title = _text(source.get("title"), "source title")
    _, display = _duration(source.get("duration_seconds"), "source duration")
    uploader = _text(metadata.get("uploader"), "metadata uploader")
    origin = metadata.get("source")
    _require(
        isinstance(origin, dict) and origin.get("kind") == "url",
        "metadata source must be a URL",
    )
    url = _text(origin.get("value"), "metadata source URL")
    parsed = urlsplit(url)
    _require(
        parsed.scheme in {"http", "https"} and bool(parsed.netloc),
        f"metadata source URL must use HTTP(S): {url}",
    )
    target = PurePosixPath(sources.name) / lane_path / read_path
    link = "/".join(quote(part, safe="-._~") for part in target.parts)
    return (
        MARKDOWN.sub(r"\\\1", title),
        link,
        MARKDOWN.sub(r"\\\1", uploader),
        display,
        quote(url, safe=":/?#[]@!$&'*+,;=%"),
    )


def render_index(manifest_path: Path = MANIFEST) -> str:
    manifest = _object(manifest_path)
    _require(
        manifest.get("schema_version") == "5" and manifest.get("tool") == "vctx",
        "expected a vctx schema-5 manifest",
    )
    _require(manifest.get("status") == "ok", "pack is not ready")
    sources = manifest.get("sources")
    _require(isinstance(sources, list), "manifest sources must be a list")

    entries = [_entry(manifest_path.parent, source) for source in sources]
    blocks = (
        f"{number}. [{title}]({read_path})\n"
        f"   - Uploader: {uploader}\n"
        f"   - Duration: `{duration}`\n"
        f"   - Source: [Original video]({url})"
        for number, (title, read_path, uploader, duration, url) in enumerate(
            reversed(entries), 1
        )
    )
    body = "\n\n".join(blocks) or "No recordings are currently indexed."
    return f"{HEADER}{body}\n"


def check_index(manifest_path: Path = MANIFEST, output_path: Path = INDEX) -> bool:
    expected = render_index(manifest_path).encode()
    return output_path.is_file() and output_path.read_bytes() == expected


def write_index(manifest_path: Path = MANIFEST, output_path: Path = INDEX) -> None:
    output_path.parent.mkdir(parents=True, exist_ok=True)
    temporary = None
    try:
        with tempfile.NamedTemporaryFile(dir=output_path.parent, delete=False) as stream:
            temporary = Path(stream.name)
            stream.write(render_index(manifest_path).encode())
        temporary.replace(output_path)
    finally:
        if temporary:
            temporary.unlink(missing_ok=True)


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true", help="fail if the index is stale")
    args = parser.parse_args()
    try:
        if args.check:
            if check_index():
                return 0
            print("INDEX.md is stale; run: python tools/build_index.py", file=sys.stderr)
            return 1
        write_index()
        return 0
    except (CatalogError, json.JSONDecodeError, OSError) as error:
        parser.exit(2, f"error: {error}\n")


if __name__ == "__main__":
    raise SystemExit(main())
